'use strict';

/* ---------- Hora Santa — Apostolado da Oração ---------- */
/* Roteiro mensal (Janeiro a Dezembro) com as falas do Padre (sacerdote) e
   as respostas do Povo/Todos (assembleia), a partir do documento
   "Hora Santa - Apostolado da Oração". Dezembro está marcado como
   incompleto porque o documento de origem só traz os cânticos de
   abertura daquele mês, sem o corpo da oração. */

const HORA_SANTA_MESES = [{"slug":"janeiro","mes":"Janeiro","completo":true,"blocos":[{"tipo":"nota","texto":"Cântico para entrada do Santíssimo e incensação."},{"tipo":"nota","texto":"Cântico para início da Hora Santa: \"Ó Vinde a Nós, Espírito Santo\"."},{"tipo":"sacerdote","texto":"Senhor Jesus Cristo, eis-nos aqui, na vossa presença nesta primeira sexta-feira deste ano. Aqui viemos Senhor para vos adorar e prestar-vos as nossas homenagens; para vos agradecer e para vos pedir. Vos agradecer por tudo o que nos fizestes e vos pedir a vossa graça para este novo ano. Que nele, cada vez mais, acreditemos e busquemos a Esperança que não decepciona."},{"tipo":"assembleia","texto":"Nós vos agradecemos, ó Jesus, em primeiro lugar, porque nos tornastes dignos de estar aqui em vossa presença e vos servir e segundo por nos dardes, de vossa bondade e misericórdia, este novo ano, este novo tempo, e nele esta ditosa graça de vos adorar e vos louvar, de entregarmos a nossa vida em vossas mãos santíssimas."},{"tipo":"sacerdote","texto":"Ah Senhor, é tão passageira a nossa existência, tão confusos os nossos sonhos, tão cansativa a nossa corrida para a realização de nossos desejos. Só Vós sois a nossa esperança, só em Vós podemos ser felizes, só a vossa presença nos tira da mesmice dos dias tão passageiros, dos meses tão corridos, dos anos que se esvaem e vão com a nossa juventude como que para o nada. Vós que sois o Peregrino do Pai, a Esperança dos que em vós esperam, amparai-nos hoje, clementíssimo Jesus, abri nossos olhos, purificai nosso coração para desejarmos apenas o que convém ao cristão: ser completamente vossos, viver e morrer em vossa presença, para alcançarmos a bem-aventurança de habitar em vosso coração."},{"tipo":"assembleia","texto":"Dividindo esta nossa hora santa em dois momentos, neste primeiro queremos vos entregar este novo ano e, portanto, suplicar a vossa benevolência da qual tanto necessitamos."},{"tipo":"sacerdote","texto":"Ouvi-nos Senhor, neste momento de graças, e concedei-nos de vosso amor o que vos pedimos nesta primeira sexta-feira de janeiro: dai-nos a graça de nos convertermos a vós de todo o nosso coração e de deixarmos, neste novo ano que se inicia, as propostas nefastas deste mundo, para nos apegarmos somente a vós e ao que nos propõe o vosso amor. Quanto quer reinar e dominar nosso coração o egoísmo, o orgulho, a vaidade e todos os mais perigosos pecados mortais. Que não sejam estes nossos soberanos. Por isso, Sacratíssimo Coração de Jesus, que estais vivo e presente nesta Hóstia santa, pura e imaculada, nós, vossos servos e também vosso povo santo, vos suplicamos nesta primeira hora santa do ano: Reinai em nossos corações! Ó Coração divino de Jesus Redentor, vinde abrasar-nos nas chamas de vosso divino amor."},{"tipo":"assembleia","texto":"Bem sabeis ó Jesus quanto já fomos tentados nestes poucos dias deste novo ano... bem sabeis as lutas que já travamos nestes primeiros momentos de um ano que tanto desejamos dedicar ao vosso Coração. Vós que conheceis a nossa fraqueza, o barro de que fomos feitos e os desejos que atribulam o nosso pensamento, não permitais que sejamos tentados acima de nossas forças, mas concedei-nos, Jesus sacramentado, o favor de que tanto precisamos nesta noite: aprendermos a desprezar as coisas exteriores, as coisas que não vêm de vós e que não nos levam para vós, para absorvermos, em nosso coração, somente aquilo que colocastes no nosso interior: o desejo ardente de vós, a vontade de somente vos servir e de devolver-vos aquilo que nos destes ao submetermos a vós a nossa vida com todas as nossas forças e a nossa alma com todas as suas potências."},{"tipo":"sacerdote","texto":"Vós que nos fizestes para vós, que ao criar-nos deixastes em nós um vínculo que jamais se desfez, vínculo que nos mantém unidos a vós qual cordão umbilical que une o feto à sua mãe, dai-nos Senhor compreender que sem vós jamais seremos felizes, que sem vós jamais alcançaremos a vida e que sem vós jamais viveremos em paz. Dai-nos piedosíssimo Jesus compreender que só vós sois a felicidade, só vós sois a vida e o vosso reino é paz e alegria no Espírito Santo, o qual não se dá aos que não têm fé."},{"tipo":"assembleia","texto":"Diante do que sois e daquilo que somos, resta-nos Senhor vos implorar: infundi em nós, neste novo tempo, a graça de prepararmos a nossa vida e o nosso coração para acolher-vos. Fazei de nós, divino benfeitor, a vossa morada, para que vós se manifestes em nossa vida e nos consoles, para que possamos ver e sentir toda a vossa glória e formosura e deste modo deixar que nossa alma seja transformada pela vossa presença."},{"tipo":"sacerdote","texto":"Fazei Senhor que neste ano que agora se inicia jamais nos esqueçamos de vós, mas deixemos a nós mesmos para lembrar-nos somente da Vossa bondade. Que possamos colocar em vós toda a nossa confiança e o nosso amor e que seja vós, dulcíssimo Senhor, a nossa esperança, o nosso amor e a nossa afeição. Fazei-nos compreender que não temos aqui morada permanente, pois, nesta vida, somos peregrinos que marchamos para vós."},{"tipo":"nota","texto":"Cântico."},{"tipo":"nota","texto":"Leitura bíblica."},{"tipo":"nota","texto":"Cântico."},{"tipo":"sacerdote","texto":"Neste segundo momento da nossa Hora Santa, queremos ó diviníssimo Jesus, vos agradecer por tanto amor, por ter-nos preparado tudo o que precisamos para que a nossa vida seja repleta de alegria em vossa presença."},{"tipo":"assembleia","texto":"Ó Jesus sacramentado, que por amor infinito e insondável nos dais a vossa presença para nos consolar e nos aliviar de nossos fardos, e, o vosso Corpo e Sangue como alimento que nos encoraja nesta caminhada rumo ao céu. Neste ano que se inicia, a nossa atitude perante vós seja de agradecimento. Que podemos vos oferecer além de nossas vidas? Ou que ação de graças poderia igualar os benefícios que nos fazes? Quão grandes e incompreensíveis são as graças que nos concedes... por isso, prostrados aos pés de vosso altar, queremos vos agradecer por tanto nos amardes ó Jesus!"},{"tipo":"assembleia","texto":"Nós vos agradecemos ó Deus e Senhor nosso por nos terdes dado a vida e todas as criaturas que destinastes ao nosso serviço, e por nos terdes feito guardiões da vossa criação e jardineiros da natureza que tão belamente fizestes. Ela é forte e cheia de encantos, generosa e graciosa, nela imprimistes as estações e os tempos para o nosso deleite, nos destes o que precisamos para saciar as nossas necessidades materiais e imprimistes em cada uma de suas particularidades os sinais de que nos amas, ó Senhor."},{"tipo":"sacerdote","texto":"Nós vos agradecemos ó piedosíssimo Jesus, vos terdes feito homem por nosso amor e morrido na cruz para nos salvar, resgatando-nos das profundezas do abismo infernal e lavando-nos do pecado original com vosso precioso sangue."},{"tipo":"assembleia","texto":"Nós vos agradecemos pela Santa Igreja Católica que fundastes na terra, os santos sacramentos que instituístes, por nos terdes feito nascer na fé católica e apostólica, nela nos ter conservado até hoje, e por não terdes nos deixado morrer em pecado, dando-nos o tempo e a graça suficiente para fazermos penitência."},{"tipo":"sacerdote","texto":"Nós vos agradecemos todas as graças que continuamente nos concedeis para a nossa santificação, bem como todos os benefícios que a cada passo nos dispensais."},{"tipo":"assembleia","texto":"De modo especial, Senhor, queremos vos agradecer pelo Santíssimo Sacramento da Eucaristia, pelo qual vos fazes presente entre nós e nos alimentas a alma, dando-nos vida, força, consolação e alento."},{"tipo":"sacerdote","texto":"Nós vos agradecemos hoje, em particular as graças que nos concedes nesta hora santa, em que nos permites estarmos juntos, diante de vossa presença. Desta Hóstia Santa, Pão Vivo descido do Céu, onde pulsa de amor o vosso Coração, fonte inesgotável de todas as graças e bênçãos, derramai sobre a vossa Igreja e sobre o Santo Padre o Papa, sobre a nossa diocese e sobre o nosso bispo, sobre a nossa paróquia, sobre o nosso pároco e todos os nossos padres, sobre os coordenadores e membros das pastorais, movimentos e associações as virtudes da santidade, unidade, da perseverança em vosso serviço e do amor que devemos ter para com a Sagrada Eucaristia."},{"tipo":"assembleia","texto":"Ó Jesus amável, desejamos que toda a nossa vida seja um ato contínuo de agradecimento, por tudo quanto fizestes por nós com tanta bondade e misericórdia. Fazei que eu vos possa louvar e bendizer num hino perpétuo de ação de graças, com todos os anjos e santos do Céu, pelos séculos dos séculos. Amém."},{"tipo":"nota","texto":"Bênção do Santíssimo completa."}]},{"slug":"fevereiro","mes":"Fevereiro","completo":true,"blocos":[{"tipo":"nota","texto":"Cântico para entrada do Santíssimo e incensação."},{"tipo":"nota","texto":"Cântico para início da Hora Santa: \"Ó Vinde a Nós, Espírito Santo\"."},{"tipo":"sacerdote","texto":"Recebei, ó Jesus sacramentado, este momento de adoração, momento em que minha alma vive a paz e o amor. Quão grande, Senhor, é a abundância da doçura que reservastes aos que vos temem, vos amam de todo o coração e vos servem! É verdadeiramente inefável a doçura da contemplação que concedeis aos que vos amam. Nisto particularmente me manifestastes a doçura de vosso amor: quando eu não era, vós me criastes e quando eu andava longe de vós, perdido no erro, vós me reconduzistes a vos servir e me destes o preceito de vos amar."},{"tipo":"assembleia","texto":"Ó fonte perene de amor, que direi de vós? Como poderia eu esquecer-me que vos dignastes lembrar-vos de mim, ainda depois de depravado e perdido? Além de toda esperança, usastes de misericórdia para com vosso servo, e acima de todo mérito me prodigalizastes vossa graça e amizade. Com que poderei agradecer-vos tal mercê? Será porventura mérito que eu vos sirva, quando toda criatura tem obrigação de vos servir? Não me deve parecer grande coisa que eu vos sirva; antes devo considerar grande e digno de admiração que vos digneis receber-me pobre e indigno como sou em vosso serviço e associar-me aos vossos servos prediletos."},{"tipo":"sacerdote","texto":"Vede, é vosso, Senhor, tudo que possuo e com que vos sirvo; entretanto, mais me servis vós a mim, do que eu a vós. Aí estão o céu e a terra, que criastes para uso do homem, e estão atentos a vosso aceno, a fazer cada dia o que lhes mandais. Mais ainda: os próprios anjos destinastes ao serviço do homem. Mas, acima de tudo isso, vós mesmo vos dignais servir ao homem, e prometestes ser a sua recompensa."},{"tipo":"assembleia","texto":"Que vos darei eu por esses benefícios sem conta? Oh! se pudera servir-vos todos os dias da minha vida! Se pudera, ainda que um só dia, prestar-vos condigno serviço! Na verdade, sois digno de todo serviço, de toda honra e glória eterna. Vós sois, verdadeiramente, meu Senhor, eu vosso pobre servidor, obrigado a servir-vos com todas as minhas forças, sem me cansar jamais de vos dar louvores. Assim o quero, assim o desejo: dignai-vos, Senhor, suprir o que me falta."},{"tipo":"sacerdote","texto":"Grande honra e glória é servir-vos e desprezar tudo por vosso amor. Porque copiosas graças alcançarão os que livremente se sujeitam ao vosso santíssimo serviço. Encontrarão suavíssima consolação do Espírito Santo os que por vós desprezam todos os deleites carnais. Conseguirão grande liberdade da alma os que por vosso nome entram na vereda estreita e se apartam de todos os cuidados mundanos."},{"tipo":"assembleia","texto":"Ó doce e amável servidão de Deus, que torna o homem verdadeiramente livre e santo! Ó sagrada servidão, que faz o homem agradável a Deus! Ó ditoso e nunca assaz desejado serviço, que nos mereceu o Bem soberano e adquire o gozo que há de durar para sempre!"},{"tipo":"nota","texto":"Cântico."},{"tipo":"nota","texto":"Leitura bíblica."},{"tipo":"nota","texto":"Cântico."},{"tipo":"sacerdote","texto":"Ó Jesus, Criador e Redentor nosso, nós vos adoramos presente neste santo altar e cremos que verdadeiramente estás aqui, vivo e glorioso neste Augusto Sacramento, com vosso Corpo e Sangue, Alma e Divindade, tão real e perfeitamente como estais no céu. Nós vos reverenciamos e nos curvamos ante a vossa presença com o mais profundo respeito, bendizemos a vossa Divina Majestade, glorificamos a vossa magnificência, e louvamos a vossa beleza infinita. Ó quão sublime este momento em que diante de vós vos submetemos o nosso coração com todos os seus afetos, a nossa alma com todas as suas potências e o nosso pensamento."},{"tipo":"assembleia","texto":"Só Vós, ó Jesus, sois a nossa consolação! Por isso humildemente vos pedimos: permita-nos neste momento de paz e amor descansarmos em vosso sacratíssimo Coração, pois, só vós sois a alegria e a felicidade de nossas almas! Só em vós elas, cansadas e oprimidas pelo peso do pecado e das suas nefastas consequências, encontram o alívio e o socorro de que tanto necessitam. Só a Vós, Senhor, todas as criaturas no céu e na terra devem render glória e adoração."},{"tipo":"sacerdote","texto":"Nós vos adoramos, ó Bom Jesus, em nome de todas as criaturas, em nome de tudo o que criastes, o céu com suas potências, a terra com tudo o que lhe é próprio e o mar com seus mistérios. Tudo tu criaste por amor e por misericórdia infinita. Nós te adoramos em nome das tuas criaturas, principalmente daquelas que não vos adoram."},{"tipo":"assembleia","texto":"E para que a nossa pobre adoração mais vos agrade, nós vos oferecemos, ó Divino Redentor, todos os atos de adoração dos santos apóstolos e confessores, dos gloriosos mártires e das santas virgens, dos Anjos que vos fazem guarda de honra aqui diante do sagrado tabernáculo, dos Arcanjos que estão diante do vosso trono no céu, e de todos os Querubins e Serafins, Potestades, Principados e Virtudes, Tronos e Dominações."},{"tipo":"sacerdote","texto":"Em particular, vos oferecemos, amado Jesus, a adoração do apóstolo São João, vosso amigo angélico, que na noite memorável da santa Ceia encostou a cabeça em vosso peito para ouvir o vosso coração; de São José vosso pai putativo que tanto vos ama e a quem escolhestes para ser o vosso provedor e guarda zeloso na vossa infância e sobretudo da Santíssima Virgem Maria, vossa mãe imaculada, que antes de conceber-vos em seu ventre já vos concebia em seu coração e que vos acompanhou por toda a vida desde o vosso nascimento na gruta de Belém até o momento em que fostes colocado no sepulcro pela nossa salvação."},{"tipo":"assembleia","texto":"Aceitai propício e benigno, ó divino Salvador nosso, este ato de adoração que vos fazemos, em união com os vossos anjos e santos e pelo Coração puríssimo de vossa Mãe Imaculada, e fazei que sempre nos aproximemos de vós com a mais viva fé, devoção e amor, a fim de termos a dita inefável de adorar-vos um dia com os anjos e santos, na eterna glória do céu."},{"tipo":"nota","texto":"Bênção do Santíssimo completa."}]},{"slug":"marco","mes":"Março","completo":true,"blocos":[{"tipo":"nota","texto":"Cântico para entrada do Santíssimo e incensação."},{"tipo":"nota","texto":"Cântico para início da Hora Santa: \"Ó Vinde a Nós, Espírito Santo\"."},{"tipo":"sacerdote","texto":"Vinde, ó Deus, em meu auxílio."},{"tipo":"assembleia","texto":"Socorrei-me sem demora."},{"tipo":"sacerdote","texto":"Glória ao Pai e ao Filho e ao Espírito Santo."},{"tipo":"assembleia","texto":"Como era no princípio, agora e sempre. Amém."},{"tipo":"sacerdote","texto":"A abstinência quaresmal vós consagrastes, ó Jesus; pelo jejum e pela prece, nos conduzis da treva à luz."},{"tipo":"assembleia","texto":"Ficai presente agora à Igreja, ficai presente à penitência, pela qual vos suplicamos para os pecados indulgência."},{"tipo":"sacerdote","texto":"Por vossa graça, perdoai as nossas culpas do passado; contra as futuras protegei-nos, manso Jesus, Pastor amado."},{"tipo":"assembleia","texto":"Para que nós, purificados por esses ritos anuais, nos preparemos, reverentes, para gozar os dons pascais."},{"tipo":"sacerdote","texto":"Todo o universo vos adore, Trindade Santa, Sumo Bem. Novos, por graça, vos cantemos um canto novo e belo. Amém."},{"tipo":"nota","texto":"Cântico."},{"tipo":"sacerdote","texto":"Ó Jesus, Criador e Redentor nosso, nós vos adoramos presente neste santo altar e cremos que verdadeiramente estás aqui, vivo e glorioso neste Augusto Sacramento, com vosso Corpo e Sangue, Alma e Divindade, tão real e perfeitamente como estais no céu. Nós vos reverenciamos e nos curvamos ante a vossa presença com o mais profundo respeito, bendizemos a vossa Divina Majestade, glorificamos a vossa magnificência, e louvamos a vossa beleza infinita. Ó quão sublime este momento em que diante de vós vos submetemos o nosso coração com todos os seus afetos, a nossa alma com todas as suas potências e o nosso pensamento."},{"tipo":"assembleia","texto":"Só Vós, ó Jesus, sois a nossa consolação! Por isso humildemente vos pedimos: permita-nos neste momento de paz e amor descansarmos em vosso sacratíssimo Coração, pois, só vós sois a alegria e a felicidade de nossas almas! Só em vós elas, cansadas e oprimidas pelo peso do pecado e das suas nefastas consequências, encontram o alívio e o socorro de que tanto necessitam. Só a Vós, Senhor, todas as criaturas no céu e na terra devem render glória e adoração."},{"tipo":"sacerdote","texto":"Nós vos adoramos, ó Bom Jesus, em nome de todas as criaturas, em nome de tudo o que criastes, o céu com suas potências, a terra com tudo o que lhe é próprio e o mar com seus mistérios. Tudo tu criaste por amor e por misericórdia infinita. Nós te adoramos em nome das tuas criaturas, principalmente daquelas que não vos adoram."},{"tipo":"assembleia","texto":"E para que a nossa pobre adoração mais vos agrade, nós vos oferecemos, ó Divino Redentor, todos os atos de adoração dos santos apóstolos e confessores, dos gloriosos mártires e das santas virgens, dos Anjos que vos fazem guarda de honra aqui diante do sagrado tabernáculo, dos Arcanjos que estão diante do vosso trono no céu, e de todos os Querubins e Serafins, Potestades, Principados e Virtudes, Tronos e Dominações."},{"tipo":"sacerdote","texto":"Em particular, vos oferecemos, amado Jesus, a adoração do apóstolo São João, vosso amigo angélico, que na noite memorável da santa Ceia encostou a cabeça em vosso peito para ouvir o vosso coração; de São José vosso pai putativo que tanto vos ama e a quem escolhestes para ser o vosso provedor e guarda zeloso na vossa infância e sobretudo da Santíssima Virgem Maria, vossa mãe imaculada, que antes de conceber-vos em seu ventre já vos concebia em seu coração e que vos acompanhou por toda a vida desde o vosso nascimento na gruta de Belém até o momento em que fostes colocado no sepulcro pela nossa salvação."},{"tipo":"assembleia","texto":"Aceitai propício e benigno, ó divino Salvador nosso, este ato de adoração que vos fazemos, em união com os vossos anjos e santos e pelo Coração puríssimo de vossa Mãe Imaculada, e fazei que sempre nos aproximemos de vós com a mais viva fé, devoção e amor, a fim de termos a dita inefável de adorar-vos um dia com os anjos e santos, na eterna glória do céu."},{"tipo":"nota","texto":"Cântico."},{"tipo":"nota","texto":"Leitura bíblica."},{"tipo":"nota","texto":"Cântico."},{"tipo":"sacerdote","texto":"Ó Jesus Sacramentado, vós sois a fonte de todos os bens. Vós nos dizeis: \"Se alguém tem sede, venha a mim e beba\" (Jo 7,37). Oh! Com que abundância os Santos sempre têm bebido as águas da graça nesta fonte do Santíssimo Sacramento, onde Jesus nos reparte todos os méritos de sua Paixão, conforme predisse o profeta: \"Ireis, cheios de alegria, tomar as águas das fontes do Salvador\" (Is 12,3)."},{"tipo":"assembleia","texto":"Ó Jesus amantíssimo, dulcíssimo e caríssimo, vós sois a vida, esperança, tesouro e único amor de nossas almas; oh! Quanto vos custou a permanência conosco neste Sacramento! Para ficardes sobre os nossos altares vos foi preciso morrer na cruz. E depois, neste Sacramento, quantas injúrias sofreis para estardes presente no meio de nós! Mas, venceu o Vosso amor, venceu o desejo que tendes de ser amado de nós."},{"tipo":"sacerdote","texto":"Vinde, pois, Senhor, vinde, encerrai-Vos no nosso coração e trancai-lhe a porta para sempre, a fim de que nenhuma criatura entre nele para roubar o amor que Vos devemos e queremos dar-Vos sem reserva. Reinai, ó amado Redentor, reinai sobre nós e possuí-nos; e, se alguma vez não Vos obedecermos perfeitamente, exortai-nos Senhor para que sejamos mais atentos em Vos amar, agradar e fazer a Vossa vontade."},{"tipo":"assembleia","texto":"Fazei Senhor que não desejemos nem busquemos outro prazer mais que o de Vos amar e sermos agradáveis a vós, Visitar-Vos muitas vezes nos altares, quedar-vos aos pés de vossos sacrários, entreter-nos convosco e receber-Vos na santa comunhão. Outros bens procurem quem os quiser, nós porém, só a vós amamos e só desejamos o tesouro do Vosso amor: isto só, e nada mais vos queremos pedir aos pés do altar."},{"tipo":"sacerdote","texto":"Fazei Senhor que nos esqueçamos de nós mesmos, para lembrar-nos somente da Vossa bondade. Ó bem-aventurados Serafins, vós que vos abrasais de amor diante da Santíssima Trindade, não vos admiramos pela vossa glória, mas pelo amor que consagrais a Deus; ensinai-nos o que devemos fazer para O amar e sermos-lhes agradáveis. Ó Bom Jesus, só a Vós queremos amar, só a Vós queremos agradar."},{"tipo":"sacerdote","texto":"Ó Cordeiro sem mancha, imolado por nós na cruz, lembrai-Vos que somos as almas que remistes com tantas dores e com a vossa própria morte. Fazei que sejais todo nosso e que nunca mais Vos percamos, já que Vos destes todo a nós e Vos dais ainda cada dia, doando-vos por nosso amor sobre os altares. Pedimos-vos a graça de sermos também nós todos vossos."},{"tipo":"assembleia","texto":"Neste momento, damo-nos todo a Vós, para que façais de nós o que Vos aprouver. Damos-vos a nossa vontade: prendei-a com as suaves cadeias do Vosso amor, a fim de que seja para sempre serva da Vossa santíssima vontade."},{"tipo":"sacerdote","texto":"Não queremos mais viver para satisfazer os nossos desejos, mas somente para contentar a Vossa vontade. Destruí em nós, ó amado Jesus, tudo o que Vos desagrada; dai-nos a graça de só pensar em Vos agradar, e de só querer o que Vós quereis. Amamos-vos, ó querido Salvador, de todo o nosso coração; amamos-vos porque quereis ser amado por nós; amamos-vos porque sois infinitamente digno do nosso amor. Pesa-nos, Senhor, não poder amar-Vos quanto o mereceis. Ah! Pudéssemos morrer por Vosso amor! Aceitai, Senhor, este nosso desejo e dai-nos o Vosso amor."},{"tipo":"assembleia","texto":"A minha alma engrandece ao Senhor e exulta meu espírito em Deus, meu Salvador; porque olhou para a humildade de sua serva, doravante as gerações hão de chamar-me de bendita. O Poderoso fez em mim maravilhas e Santo é o seu nome! Seu amor para sempre se estende sobre aqueles que o temem; manifestou o poder de seu braço, dispersou os soberbos. Derrubou os poderosos de seus tronos e elevou os humildes. De bens saciou os famintos, e despediu, sem nada, os ricos. Acolheu Israel, seu servidor, fiel ao seu amor, como havia prometido a nossos pais, em favor de Abraão e de seus filhos, para sempre. Glória ao Pai e ao Filho e ao Espírito Santo. Como era no princípio, agora e sempre. Amém."},{"tipo":"nota","texto":"Bênção do Santíssimo completa."}]},{"slug":"abril","mes":"Abril","completo":true,"blocos":[{"tipo":"nota","texto":"Cântico para entrada do Santíssimo e incensação."},{"tipo":"nota","texto":"Cântico para início da Hora Santa: \"Ó Vinde a Nós, Espírito Santo\"."},{"tipo":"assembleia","texto":"Senhor meu Jesus Cristo, que, por amor aos homens, ficais dia e noite neste Sacramento, todo cheio de misericórdia e amor, esperando, chamando e acolhendo todos os que vêm visitar-Vos, eu creio que estais presente no Sacramento do altar. Adoro-Vos do abismo do meu nada e agradeço-Vos todas as graças que me tendes feito, especialmente a de Vos terdes dado a mim neste Sacramento, a de me haverdes concedido por advogada Maria, vossa Mãe Santíssima, e finalmente, a de me haverdes chamado a visitar-Vos nesta Igreja."},{"tipo":"assembleia","texto":"Saúdo hoje o vosso Coração amantíssimo e quero saudá-lo por três fins: primeiro, em agradecimento pelo grande dom de Vós mesmo; segundo, em reparação das injúrias que tendes recebido, neste Sacramento, de todos os vossos inimigos; terceiro, com a intenção de Vos adorar, por esta visita, em todos os lugares da Terra onde Vós, neste divino Sacramento, estais menos reverenciado e mais abandonado."},{"tipo":"assembleia","texto":"Meu Jesus, amo-Vos de todo o meu coração. Arrependendo-me de, no passado, ter ofendido tantas vezes a vossa bondade infinita. Proponho, com a vossa graça, não mais Vos ofender no futuro. E nesta hora, embora miserável como sou, eu me consagro todo a Vós e Vos dou e entrego a minha vontade, os meus afetos, os meus desejos e tudo o que me pertence. Daqui em diante fazei de mim, e de tudo o que é meu, o que Vos aprouver. Somente Vos peço e quero o vosso santo amor, a perseverança final e o perfeito cumprimento da vossa vontade."},{"tipo":"assembleia","texto":"Recomendo-Vos as almas do Purgatório, especialmente as mais devotas do Santíssimo Sacramento e da Santíssima Virgem Maria. Recomendo-Vos também todos os pobres pecadores. Enfim, meu amado Salvador, uno todos os meus afetos aos afetos do vosso Coração amantíssimo e, assim unidos, eu os ofereço a vosso Eterno Pai, pedindo-Lhe, em Vosso nome e por vosso amor, que Se digne de os aceitar e atender. Assim seja."},{"tipo":"nota","texto":"Cântico."},{"tipo":"nota","texto":"Leitura bíblica."},{"tipo":"nota","texto":"Cântico."},{"tipo":"sacerdote","texto":"Recebei, ó Jesus sacramentado, este momento de adoração, momento em que minha alma vive a paz e o amor. Quão grande, Senhor, é a abundância da doçura que reservastes aos que vos temem, vos amam de todo o coração e vos servem! É verdadeiramente inefável a doçura da contemplação que concedeis aos que vos amam. Nisto particularmente me manifestastes a doçura de vosso amor: quando eu não era, vós me criastes e quando eu andava longe de vós, perdido no erro, vós me reconduzistes a vos servir e me destes o preceito de vos amar."},{"tipo":"assembleia","texto":"Ó fonte perene de amor, que direi de vós? Como poderia eu esquecer-me que vos dignastes lembrar-vos de mim, ainda depois de depravado e perdido? Além de toda esperança, usastes de misericórdia para com vosso servo, e acima de todo mérito me prodigalizastes vossa graça e amizade. Com que poderei agradecer-vos tal mercê? Será porventura mérito que eu vos sirva, quando toda criatura tem obrigação de vos servir? Não me deve parecer grande coisa que eu vos sirva; antes devo considerar grande e digno de admiração que vos digneis receber-me pobre e indigno como sou em vosso serviço e associar-me aos vossos servos prediletos."},{"tipo":"sacerdote","texto":"Vede, é vosso, Senhor, tudo que possuo e com que vos sirvo; entretanto, mais me servis vós a mim, do que eu a vós. Aí estão o céu e a terra, que criastes para uso do homem, e estão atentos a vosso aceno, a fazer cada dia o que lhes mandais. Mais ainda: os próprios anjos destinastes ao serviço do homem. Mas, acima de tudo isso, vós mesmo vos dignais servir ao homem, e prometestes ser a sua recompensa."},{"tipo":"assembleia","texto":"Que vos darei eu por esses benefícios sem conta? Oh! se pudera servir-vos todos os dias da minha vida! Se pudera, ainda que um só dia, prestar-vos condigno serviço! Na verdade, sois digno de todo serviço, de toda honra e glória eterna. Vós sois, verdadeiramente, meu Senhor, eu vosso pobre servidor, obrigado a servir-vos com todas as minhas forças, sem me cansar jamais de vos dar louvores. Assim o quero, assim o desejo: dignai-vos, Senhor, suprir o que me falta."},{"tipo":"sacerdote","texto":"Grande honra e glória é servir-vos e desprezar tudo por vosso amor. Porque copiosas graças alcançarão os que livremente se sujeitam ao vosso santíssimo serviço. Encontrarão suavíssima consolação do Espírito Santo os que por vós desprezam todos os deleites carnais. Conseguirão grande liberdade da alma os que por vosso nome entram na vereda estreita e se apartam de todos os cuidados mundanos."},{"tipo":"assembleia","texto":"Ó doce e amável servidão de Deus, que torna o homem verdadeiramente livre e santo! Ó sagrada servidão, que faz o homem agradável a Deus! Ó ditoso e nunca assaz desejado serviço, que nos mereceu o Bem soberano e adquire o gozo que há de durar para sempre!"},{"tipo":"nota","texto":"Bênção do Santíssimo completa."}]},{"slug":"maio","mes":"Maio","completo":true,"blocos":[{"tipo":"nota","texto":"Cântico para entrada do Santíssimo e incensação."},{"tipo":"nota","texto":"Cântico para início da Hora Santa: \"Ó Vinde a Nós, Espírito Santo\"."},{"tipo":"nota","texto":"Oração inicial."},{"tipo":"assembleia","texto":"Ó dulcíssimo Jesus, pedimos-vos nesta hora, por intercessão da Virgem Maria, vossa Santíssima Mãe e Senhora do Santíssimo Sacramento, que mereceu unicamente por graça divina trazer em seu seio puríssimo a vós, Verbo de Deus que se entregou por nós na Cruz e nos alimenta com seu Corpo e Sangue na Mesa da Comunhão, concedei-nos um amor semelhante ao que ela vos tem, para que a nossa adoração seja perfeita e as nossas palavras e ações segundo a vossa vontade."},{"tipo":"nota","texto":"(Rezar a dezena do terço pelas vocações sacerdotais e religiosas.)"},{"tipo":"nota","texto":"Cântico."},{"tipo":"nota","texto":"Diálogo com o Senhor."},{"tipo":"sacerdote","texto":"Ó Jesus Sacramentado, vós sois a fonte de todos os bens. Vós nos dizeis: \"Se alguém tem sede, venha a mim e beba\" (Jo 7,37). Oh! Com que abundância os Santos sempre têm bebido as águas da graça nesta fonte do Santíssimo Sacramento, onde Jesus nos reparte todos os méritos de sua Paixão, conforme predisse o profeta: \"Ireis, cheios de alegria, tomar as águas das fontes do Salvador\" (Is 12,3)."},{"tipo":"assembleia","texto":"Ó Jesus amantíssimo, dulcíssimo e caríssimo, vós sois a vida, esperança, tesouro e único amor de nossas almas; oh! Quanto vos custou a permanência conosco neste Sacramento! Para ficardes sobre os nossos altares vos foi preciso morrer na cruz. E depois, neste Sacramento, quantas injúrias sofreis para estardes presente no meio de nós! Mas, venceu o Vosso amor, venceu o desejo que tendes de ser amado de nós."},{"tipo":"sacerdote","texto":"Vinde, pois, Senhor, vinde, encerrai-Vos no nosso coração e trancai-lhe a porta para sempre, a fim de que nenhuma criatura entre nele para roubar o amor que Vos devemos e queremos dar-Vos sem reserva. Reinai, ó amado Redentor, reinai sobre nós e possuí-nos; e, se alguma vez não Vos obedecermos perfeitamente, exortai-nos Senhor para que sejamos mais atentos em Vos amar, agradar e fazer a Vossa vontade."},{"tipo":"assembleia","texto":"Fazei Senhor que não desejemos nem busquemos outro prazer mais que o de Vos amar e sermos agradáveis a vós, Visitar-Vos muitas vezes nos altares, quedar-vos aos pés de vossos sacrários, entreter-nos convosco e receber-Vos na santa comunhão. Outros bens procurem quem os quiser, nós porém, só a vós amamos e só desejamos o tesouro do Vosso amor: isto só, e nada mais vos queremos pedir aos pés do altar."},{"tipo":"sacerdote","texto":"Fazei Senhor que nos esqueçamos de nós mesmos, para lembrar-nos somente da Vossa bondade. Ó bem-aventurados Serafins, vós que vos abrasais de amor diante da Santíssima Trindade, não vos admiramos pela vossa glória, mas pelo amor que consagrais a Deus; ensinai-nos o que devemos fazer para O amar e sermos-lhes agradáveis. Ó Bom Jesus, só a Vós queremos amar, só a Vós queremos agradar."},{"tipo":"sacerdote","texto":"Ó Cordeiro sem mancha, imolado por nós na cruz, lembrai-Vos que somos as almas que remistes com tantas dores e com a vossa própria morte. Fazei que sejais todo nosso e que nunca mais Vos percamos, já que Vos destes todo a nós e Vos dais ainda cada dia, doando-vos por nosso amor sobre os altares. Pedimos-vos a graça de sermos também nós todos vossos."},{"tipo":"assembleia","texto":"Neste momento, damo-nos todo a Vós, para que façais de nós o que Vos aprouver. Damos-vos a nossa vontade: prendei-a com as suaves cadeias do Vosso amor, a fim de que seja para sempre serva da Vossa santíssima vontade."},{"tipo":"sacerdote","texto":"Não queremos mais viver para satisfazer os nossos desejos, mas somente para contentar a Vossa vontade. Destruí em nós, ó amado Jesus, tudo o que Vos desagrada; dai-nos a graça de só pensar em Vos agradar, e de só querer o que Vós quereis. Amamos-vos, ó querido Salvador, de todo o nosso coração; amamos-vos porque quereis ser amado por nós; amamos-vos porque sois infinitamente digno do nosso amor. Pesa-nos, Senhor, não poder amar-Vos quanto o mereceis. Ah! Pudéssemos morrer por Vosso amor! Aceitai, Senhor, este nosso desejo e dai-nos o Vosso amor."},{"tipo":"nota","texto":"Cântico."},{"tipo":"nota","texto":"Leitura bíblica."},{"tipo":"nota","texto":"Façamos, irmãos, um momento de silêncio e oração pessoal para que a Palavra de Deus adentre em nosso coração (10 minutos)."},{"tipo":"nota","texto":"Cântico."},{"tipo":"sacerdote","texto":"Recebei, ó Jesus sacramentado, este momento de adoração, momento em que minha alma vive a paz e o amor. Quão grande, Senhor, é a abundância da doçura que reservastes aos que vos temem, vos amam de todo o coração e vos servem! É verdadeiramente inefável a doçura da contemplação que concedeis aos que vos amam. Nisto particularmente me manifestastes a doçura de vosso amor: quando eu não era, vós me criastes e quando eu andava longe de vós, perdido no erro, vós me reconduzistes a vos servir e me destes o preceito de vos amar."},{"tipo":"assembleia","texto":"Ó fonte perene de amor, que direi de vós? Como poderia eu esquecer-me que vos dignastes lembrar-vos de mim, ainda depois de depravado e perdido? Além de toda esperança, usastes de misericórdia para com vosso servo, e acima de todo mérito me prodigalizastes vossa graça e amizade. Com que poderei agradecer-vos tal mercê? Será porventura mérito que eu vos sirva, quando toda criatura tem obrigação de vos servir? Não me deve parecer grande coisa que eu vos sirva; antes devo considerar grande e digno de admiração que vos digneis receber-me pobre e indigno como sou em vosso serviço e associar-me aos vossos servos prediletos."},{"tipo":"sacerdote","texto":"Vede, é vosso, Senhor, tudo que possuo e com que vos sirvo; entretanto, mais me servis vós a mim, do que eu a vós. Aí estão o céu e a terra, que criastes para uso do homem, e estão atentos a vosso aceno, a fazer cada dia o que lhes mandais. Mais ainda: os próprios anjos destinastes ao serviço do homem. Mas, acima de tudo isso, vós mesmo vos dignais servir ao homem, e prometestes ser a sua recompensa."},{"tipo":"assembleia","texto":"Que vos darei eu por esses benefícios sem conta? Oh! se pudera servir-vos todos os dias da minha vida! Se pudera, ainda que um só dia, prestar-vos condigno serviço! Na verdade, sois digno de todo serviço, de toda honra e glória eterna. Vós sois, verdadeiramente, meu Senhor, eu vosso pobre servidor, obrigado a servir-vos com todas as minhas forças, sem me cansar jamais de vos dar louvores. Assim o quero, assim o desejo: dignai-vos, Senhor, suprir o que me falta."},{"tipo":"sacerdote","texto":"Grande honra e glória é servir-vos e desprezar tudo por vosso amor. Porque copiosas graças alcançarão os que livremente se sujeitam ao vosso santíssimo serviço. Encontrarão suavíssima consolação do Espírito Santo os que por vós desprezam todos os deleites carnais. Conseguirão grande liberdade da alma os que por vosso nome entram na vereda estreita e se apartam de todos os cuidados mundanos."},{"tipo":"assembleia","texto":"Ó doce e amável servidão de Deus, que torna o homem verdadeiramente livre e santo! Ó sagrada servidão, que faz o homem agradável a Deus! Ó ditoso e nunca assaz desejado serviço, que nos mereceu o Bem soberano e adquire o gozo que há de durar para sempre!"},{"tipo":"nota","texto":"Bênção do Santíssimo completa."}]},{"slug":"junho","mes":"Junho","completo":true,"blocos":[{"tipo":"nota","texto":"Cântico para entrada do Santíssimo e incensação."},{"tipo":"nota","texto":"Cântico para início da Hora Santa: \"Ó Vinde a Nós, Espírito Santo\"."},{"tipo":"sacerdote","texto":"Ó Meu Senhor Jesus Cristo, que pelo amor aos homens, estais dia e noite neste Santíssimo Sacramento, cheio de piedade e amor, esperando, chamando e acolhendo todos que vêm Vos visitar, nós acreditamos que estais presente no Sacramento do Altar; e vos adoramos do abismo do nosso nada, e vos agradecemos todas as graças que nos tendes feito."},{"tipo":"assembleia","texto":"Agradecemos, ó Bom Jesus, especialmente, a graça de Vós haverdes dado a Vós mesmo neste Sacramento de amor, de nos haverdes dado por advogada a vossa Santíssima Mãe Maria, e de nos haverdes chamado a vos visitar nesta Igreja, nesta hora santa."},{"tipo":"sacerdote","texto":"Nós saudamos agora ó Jesus Sacramentado, o Vosso amantíssimo Coração, e entendemos saudá-lo por três motivos: primeiro em agradecimento por este grande dom; segundo, para compensar-vos todas as injúrias que tendes recebido de todos os inimigos deste Sacramento; terceiro, porque pretendemos com esta visita Vos adorar em todos os lugares da terra, onde Vós sois menos reverenciado e mais abandonado."},{"tipo":"assembleia","texto":"Divino Jesus, nós Vos amamos com todo o nosso coração. Nos arrependemos de Vos haver desgostado tantas vezes no passado e termos sido ingratos à vossa bondade infinita. Esperamos que, amparados com a Vossa divina graça, não mais tornemos a Vos ofender de agora em diante; e agora, miseráveis que somos, nos consagramos a Vós, vos damos as nossas almas, desejosos de, por amor a Vós, renunciarmos toda a nossa vontade, afeições e desejos, bem como tudo o que possuímos."},{"tipo":"sacerdote","texto":"De hoje em diante fazei de nós, ó Jesus, e de tudo o que possuímos o que desejares. Só vos pedimos e desejamos o Vosso santo amor, a perseverança final, e o cumprimento perfeito da Vossa vontade. Vos recomendamos as almas do Purgatório, especialmente as mais devotas do Santíssimo Sacramento, e de Maria Santíssima. Vos recomendamos ainda todos os pobres pecadores. Unimo-nos enfim, ó querido Salvador, todos os nossos afetos com os afetos do Vosso amoroso Coração, e assim unidos os oferecemos ao Vosso Pai Eterno, e o pedimos em vosso Nome, que por Vosso amor os aceite e nos conceda todas as graças e bênçãos do céu."},{"tipo":"nota","texto":"Cântico."},{"tipo":"nota","texto":"Leitura bíblica."},{"tipo":"nota","texto":"Cântico."},{"tipo":"sacerdote","texto":"Ó Jesus Sacramentado, vós sois a fonte de todos os bens. Vós nos dizeis: \"Se alguém tem sede, venha a mim e beba\" (Jo 7,37). Oh! Com que abundância os Santos sempre têm bebido as águas da graça nesta fonte do Santíssimo Sacramento, onde Jesus nos reparte todos os méritos de sua Paixão, conforme predisse o profeta: \"Ireis, cheios de alegria, tomar as águas das fontes do Salvador\" (Is 12,3)."},{"tipo":"assembleia","texto":"Ó Jesus amantíssimo, dulcíssimo e caríssimo, vós sois a vida, esperança, tesouro e único amor de nossas almas; oh! Quanto vos custou a permanência conosco neste Sacramento! Para ficardes sobre os nossos altares vos foi preciso morrer na cruz. E depois, neste Sacramento, quantas injúrias sofreis para estardes presente no meio de nós! Mas, venceu o Vosso amor, venceu o desejo que tendes de ser amado de nós."},{"tipo":"sacerdote","texto":"Vinde, pois, Senhor, vinde, encerrai-Vos no nosso coração e trancai-lhe a porta para sempre, a fim de que nenhuma criatura entre nele para roubar o amor que Vos devemos e queremos dar-Vos sem reserva. Reinai, ó amado Redentor, reinai sobre nós e possuí-nos; e, se alguma vez não Vos obedecermos perfeitamente, exortai-nos Senhor para que sejamos mais atentos em Vos amar, agradar e fazer a Vossa vontade."},{"tipo":"assembleia","texto":"Fazei Senhor que não desejemos nem busquemos outro prazer mais que o de Vos amar e sermos agradáveis a vós, Visitar-Vos muitas vezes nos altares, quedar-vos aos pés de vossos sacrários, entreter-nos convosco e receber-Vos na santa comunhão. Outros bens procurem quem os quiser, nós porém, só a vós amamos e só desejamos o tesouro do Vosso amor: isto só, e nada mais vos queremos pedir aos pés do altar."},{"tipo":"nota","texto":"Cântico."},{"tipo":"sacerdote","texto":"Fazei Senhor que nos esqueçamos de nós mesmos, para lembrar-nos somente da Vossa bondade. Ó bem-aventurados Serafins, vós que vos abrasais de amor diante da Santíssima Trindade, não vos admiramos pela vossa glória, mas pelo amor que consagrais a Deus; ensinai-nos o que devemos fazer para O amar e sermos-lhes agradáveis. Ó Bom Jesus, só a Vós queremos amar, só a Vós queremos agradar."},{"tipo":"sacerdote","texto":"Ó Cordeiro sem mancha, imolado por nós na cruz, lembrai-Vos que somos as almas que remistes com tantas dores e com a vossa própria morte. Fazei que sejais todo nosso e que nunca mais Vos percamos, já que Vos destes todo a nós e Vos dais ainda cada dia, doando-vos por nosso amor sobre os altares. Pedimos-vos a graça de sermos também nós todos vossos."},{"tipo":"assembleia","texto":"Neste momento, damo-nos todo a Vós, para que façais de nós o que Vos aprouver. Damos-vos a nossa vontade: prendei-a com as suaves cadeias do Vosso amor, a fim de que seja para sempre serva da Vossa santíssima vontade."},{"tipo":"sacerdote","texto":"Não queremos mais viver para satisfazer os nossos desejos, mas somente para contentar a Vossa vontade. Destruí em nós, ó amado Jesus, tudo o que Vos desagrada; dai-nos a graça de só pensar em Vos agradar, e de só querer o que Vós quereis. Amamos-vos, ó querido Salvador, de todo o nosso coração; amamos-vos porque quereis ser amado por nós; amamos-vos porque sois infinitamente digno do nosso amor. Pesa-nos, Senhor, não poder amar-Vos quanto o mereceis. Ah! Pudéssemos morrer por Vosso amor! Aceitai, Senhor, este nosso desejo e dai-nos o Vosso amor."},{"tipo":"sacerdote","texto":"Queremos agora, Senhor nosso Deus, receber a vossa bênção santíssima. Dignai-vos ó Jesus, abrasar o nosso coração de amor por vós e nos conceder as graças e bênçãos que emanam da vossa presença sacrossanta."},{"tipo":"nota","texto":"Bênção do Santíssimo completa."}]},{"slug":"julho","mes":"Julho","completo":true,"blocos":[{"tipo":"nota","texto":"Cântico para entrada do Santíssimo e incensação."},{"tipo":"nota","texto":"Cântico para início da Hora Santa: \"Ó Vinde a Nós, Espírito Santo\"."},{"tipo":"sacerdote","texto":"Senhor Jesus, creio firmemente que estais presente em Corpo e Sangue, Alma e Divindade neste augusto Sacramento da Eucaristia, e que desejas falar-me ao coração. Fala Senhor que o vosso servo escuta: dai-me inteligência para que eu conheça os vossos ensinamentos. Inclinai meu coração às palavras de vossa boca; nele penetre, qual orvalho, vosso discurso."},{"tipo":"assembleia","texto":"Bendigo-vos, Pai celestial, por vos terdes dignado lembrar-vos de mim, pobre criatura, ó Pai de misericórdia e Deus de toda consolação! Graças vos dou Senhor Jesus porque, apesar de minha indignidade, me recriais sempre com o vosso amor. Sede para sempre bendito e glorificado neste augusto sacramento, Senhor, por todos os séculos."},{"tipo":"sacerdote","texto":"Ah! Senhor Jesus Cristo, santo amigo de minha alma, peço-vos, vinde habitar em meu coração, pois exulta de alegria o meu interior e rejubila-se a minha alma em vossas consolações. Vós sois a minha glória e o júbilo da minha vida; vós sois a minha esperança e meu refúgio no dia da tribulação."},{"tipo":"assembleia","texto":"Mas, como ainda sou fraco no amor e imperfeito na virtude, necessito ainda mais ser consolado e confortado por vós; por isso permiti-me visitar-vos mais vezes e instruí-me sempre com santas doutrinas. Livrai-me das más paixões e curai meu coração de todos os afetos desordenados, para que eu, sanado e purificado interiormente, seja apto para amar; forte para sofrer e constante para perseverar."},{"tipo":"sacerdote","texto":"Dilatai-me Senhor o amor, para que eu possa, no âmago do coração, saborear quão doce é vos amar e entregar-me a vós, deixando-me consumir como uma vela em vosso altar. Guardai-me Senhor em vosso Coração, e eleve-me acima de mim, num transporte de fervor excessivo para que eu possa unir-me mais a vós. Que na vossa presença eu cante sempre o cântico do amor; siga-vos ao alto, ó meu Amado, desfaleça minha alma no nosso louvor, no júbilo de ser desposado por vós. Amar-vos quero mais que a mim, e a mim só por amor de vós, e em vós a todos que deveras vos amam, conforme ordena a lei do amor que de vós dimana."},{"tipo":"assembleia","texto":"Fazei ó Jesus que o meu amor, em vós, seja sempre um amor pronto, sincero, piedoso, alegre e amável; forte, fiel, prudente, longânime, viril e que nunca busque a si mesmo. Pois, logo que alguém procura a si mesmo, perde o amor."},{"tipo":"sacerdote","texto":"Fazei-me compreender Senhor que o amor é circunspecto e reto; não é frouxo, não é leviano, nem cuida de coisas vãs, mas tudo suporta, tudo ama, tudo perdoa. Fazei-me ver Senhor que o amor é sempre puro, humilde, verdadeiro, afável, sóbrio, casto, constante, quieto, recatado em todos os seus sentidos; fazei-me entender que o amor é submisso e obediente aos superiores; que o amor é devoto e agradecido para convosco, e espera sempre em vós, mesmo quando está desconsolado, porque no amor não se vive sem dor."},{"tipo":"assembleia","texto":"Fazei Senhor que o meu amor seja sempre puro, santo, humilde e despretensioso, pronto, sincero, piedoso, alegre e amável e que, consciente de que sois Vós a fonte do verdadeiro amor, não busque nada mais além de ti, ó Deus de minha alma e Senhor do meu coração."},{"tipo":"nota","texto":"Cântico."},{"tipo":"nota","texto":"Leitura bíblica."},{"tipo":"nota","texto":"Cântico."},{"tipo":"sacerdote","texto":"Recebei, ó Jesus sacramentado, este momento de adoração, momento em que minha alma vive a paz e o amor. Quão grande, Senhor, é a abundância da doçura que reservastes aos que vos temem, vos amam de todo o coração e vos servem! É verdadeiramente inefável a doçura da contemplação que concedeis aos que vos amam. Nisto particularmente me manifestastes a doçura de vosso amor: quando eu não era, vós me criastes e quando eu andava longe de vós, perdido no erro, vós me reconduzistes a vos servir e me destes o preceito de vos amar."},{"tipo":"assembleia","texto":"Ó fonte perene de amor, que direi de vós? Como poderia eu esquecer-me que vos dignastes lembrar-vos de mim, ainda depois de depravado e perdido? Além de toda esperança, usastes de misericórdia para com vosso servo, e acima de todo mérito me prodigalizastes vossa graça e amizade. Com que poderei agradecer-vos tal mercê? Será porventura mérito que eu vos sirva, quando toda criatura tem obrigação de vos servir? Não me deve parecer grande coisa que eu vos sirva; antes devo considerar grande e digno de admiração que vos digneis receber-me pobre e indigno como sou em vosso serviço e associar-me aos vossos servos prediletos."},{"tipo":"sacerdote","texto":"Vede, é vosso, Senhor, tudo que possuo e com que vos sirvo; entretanto, mais me servis vós a mim, do que eu a vós. Aí estão o céu e a terra, que criastes para uso do homem, e estão atentos a vosso aceno, a fazer cada dia o que lhes mandais. Mais ainda: os próprios anjos destinastes ao serviço do homem. Mas, acima de tudo isso, vós mesmo vos dignais servir ao homem, e prometestes ser a sua recompensa."},{"tipo":"assembleia","texto":"Que vos darei eu por esses benefícios sem conta? Oh! se pudera servir-vos todos os dias da minha vida! Se pudera, ainda que um só dia, prestar-vos condigno serviço! Na verdade, sois digno de todo serviço, de toda honra e glória eterna. Vós sois, verdadeiramente, meu Senhor, eu vosso pobre servidor, obrigado a servir-vos com todas as minhas forças, sem me cansar jamais de vos dar louvores. Assim o quero, assim o desejo: dignai-vos, Senhor, suprir o que me falta."},{"tipo":"sacerdote","texto":"Grande honra e glória é servir-vos e desprezar tudo por vosso amor. Porque copiosas graças alcançarão os que livremente se sujeitam ao vosso santíssimo serviço. Encontrarão suavíssima consolação do Espírito Santo os que por vós desprezam todos os deleites carnais. Conseguirão grande liberdade da alma os que por vosso nome entram na vereda estreita e se apartam de todos os cuidados mundanos."},{"tipo":"assembleia","texto":"Ó doce e amável servidão de Deus, que torna o homem verdadeiramente livre e santo! Ó sagrada servidão, que faz o homem agradável a Deus! Ó ditoso e nunca assaz desejado serviço, que nos mereceu o Bem soberano e adquire o gozo que há de durar para sempre!"},{"tipo":"nota","texto":"Bênção do Santíssimo completa."}]},{"slug":"agosto","mes":"Agosto","completo":true,"blocos":[{"tipo":"nota","texto":"Cântico para entrada do Santíssimo e incensação."},{"tipo":"nota","texto":"Cântico para início da Hora Santa: \"Ó Vinde a Nós, Espírito Santo\"."},{"tipo":"sacerdote","texto":"Ó Jesus, Criador e Redentor nosso, nós vos adoramos presente neste santo altar e cremos que verdadeiramente estás aqui, vivo e glorioso neste Augusto Sacramento, com vosso Corpo e Sangue, Alma e Divindade, tão real e perfeitamente como estais no céu. Nós vos reverenciamos e nos curvamos ante a vossa presença com o mais profundo respeito, bendizemos a vossa Divina Majestade, glorificamos a vossa magnificência, e louvamos a vossa beleza infinita. Ó quão sublime este momento em que diante de vós vos submetemos o nosso coração com todos os seus afetos, a nossa alma com todas as suas potências e o nosso pensamento."},{"tipo":"assembleia","texto":"Só Vós, ó Jesus, sois a nossa consolação! Por isso humildemente vos pedimos: permita-nos neste momento de paz e amor descansarmos em vosso sacratíssimo Coração, pois, só vós sois a alegria e a felicidade de nossas almas! Só em vós elas, cansadas e oprimidas pelo peso do pecado e das suas nefastas consequências, encontram o alívio e o socorro de que tanto necessitam. Só a Vós, Senhor, todas as criaturas no céu e na terra devem render glória e adoração."},{"tipo":"sacerdote","texto":"Nós vos adoramos, ó Bom Jesus, em nome de todas as criaturas, em nome de tudo o que criastes, o céu com suas potências, a terra com tudo o que lhe é próprio e o mar com seus mistérios. Tudo tu criaste por amor e por misericórdia infinita. Nós te adoramos em nome das tuas criaturas, principalmente daquelas que não vos adoram."},{"tipo":"assembleia","texto":"E para que a nossa pobre adoração mais vos agrade, nós vos oferecemos, ó Divino Redentor, todos os atos de adoração dos santos apóstolos e confessores, dos gloriosos mártires e das santas virgens, dos Anjos que vos fazem guarda de honra aqui diante do sagrado tabernáculo, dos Arcanjos que estão diante do vosso trono no céu, e de todos os Querubins e Serafins, Potestades, Principados e Virtudes, Tronos e Dominações."},{"tipo":"sacerdote","texto":"Em particular, vos oferecemos, amado Jesus, a adoração do apóstolo São João, vosso amigo angélico, que na noite memorável da santa Ceia encostou a cabeça em vosso peito para ouvir o vosso coração; de São José vosso pai putativo que tanto vos ama e a quem escolhestes para ser o vosso provedor e guarda zeloso na vossa infância e sobretudo da Santíssima Virgem Maria, vossa mãe imaculada, que antes de conceber-vos em seu ventre já vos concebia em seu coração e que vos acompanhou por toda a vida desde o vosso nascimento na gruta de Belém até o momento em que fostes colocado no sepulcro pela nossa salvação."},{"tipo":"assembleia","texto":"Aceitai propício e benigno, ó divino Salvador nosso, este ato de adoração que vos fazemos, em união com os vossos anjos e santos e pelo Coração puríssimo de vossa Mãe Imaculada, e fazei que sempre nos aproximemos de vós com a mais viva fé, devoção e amor, a fim de termos a dita inefável de adorar-vos um dia com os anjos e santos, na eterna glória do céu."},{"tipo":"nota","texto":"Cântico."},{"tipo":"nota","texto":"Leitura bíblica."},{"tipo":"nota","texto":"Cântico."},{"tipo":"sacerdote","texto":"Ó clementíssimo Jesus, com que comparar o vosso amor por nós? Ou, que ação de graças poderia igualar os benefícios que nos fazes? Quão grandes e incompreensíveis são as graças que nos concedestes e todos os dias nos concedeis com liberalidade infinita, não obstante as nossas misérias e os nossos pecados. Queremos vos agradecer por tanto nos amardes ó Jesus!"},{"tipo":"assembleia","texto":"Nós vos agradecemos ó Deus e Senhor nosso por nos terdes dado a vida e todas as criaturas que destinastes ao nosso serviço, e por nos terdes feito guardiões da vossa criação e jardineiros da natureza que tão belamente fizestes. Ela é forte e cheia de encantos, generosa e graciosa, nela imprimistes as estações e os tempos para o nosso deleite, nos destes o que precisamos para saciar as nossas necessidades materiais e imprimistes em cada uma de suas particularidades os sinais de que nos amas, ó Senhor."},{"tipo":"sacerdote","texto":"Nós vos agradecemos ó piedosíssimo Jesus, vos terdes feito homem por nosso amor e morrido na cruz para nos salvar, resgatando-nos das profundezas do abismo infernal e lavando-nos do pecado original com vosso precioso sangue."},{"tipo":"assembleia","texto":"Nós vos agradecemos pela Santa Igreja Católica que fundastes na terra, os santos sacramentos que instituístes, por nos terdes feito nascer na fé católica e apostólica, nela nos ter conservado até hoje, e por não terdes nos deixado morrer em pecado, dando-nos o tempo e a graça suficiente para fazermos penitência."},{"tipo":"sacerdote","texto":"Nós vos agradecemos todas as graças que continuamente nos concedeis para a nossa santificação, bem como todos os benefícios que a cada passo nos dispensais."},{"tipo":"assembleia","texto":"De modo especial, Senhor, queremos vos agradecer pelo Santíssimo Sacramento da Eucaristia, pelo qual vos fazes presente entre nós e nos alimentas a alma, dando-nos vida, força, consolação e alento."},{"tipo":"sacerdote","texto":"Nós vos agradecemos hoje, em particular as graças que nos concedes nesta hora santa, em que nos permites estarmos juntos, diante de vossa presença. Desta Hóstia Santa, Pão Vivo descido do Céu, onde pulsa de amor o vosso Coração, fonte inesgotável de todas as graças e bênçãos, derramai sobre a vossa Igreja e sobre o Santo Padre o Papa, sobre a nossa diocese e sobre o nosso bispo, sobre a nossa paróquia, sobre o nosso pároco e todos os nossos padres, sobre os coordenadores e membros das pastorais, movimentos e associações as virtudes da santidade, unidade, da perseverança em vosso serviço e do amor que devemos ter para com a Sagrada Eucaristia."},{"tipo":"assembleia","texto":"Ó Jesus amável, desejamos que toda a nossa vida seja um ato contínuo de agradecimento, por tudo quanto fizestes por nós com tanta bondade e misericórdia. Fazei que eu vos possa louvar e bendizer num hino perpétuo de ação de graças, com todos os anjos e santos do Céu, pelos séculos dos séculos. Amém."},{"tipo":"nota","texto":"Bênção do Santíssimo completa."}]},{"slug":"setembro","mes":"Setembro","completo":true,"blocos":[{"tipo":"nota","texto":"Cântico para entrada do Santíssimo e incensação."},{"tipo":"nota","texto":"Cântico para início da Hora Santa: \"Ó Vinde a Nós, Espírito Santo\"."},{"tipo":"sacerdote","texto":"Ó Meu Senhor Jesus Cristo, que pelo amor aos homens, estais dia e noite neste Santíssimo Sacramento, cheio de piedade e amor, esperando, chamando e acolhendo todos que vêm Vos visitar, nós acreditamos que estais presente no Sacramento do Altar; e vos adoramos do abismo do nosso nada, e vos agradecemos todas as graças que nos tendes feito."},{"tipo":"assembleia","texto":"Agradecemos, ó Bom Jesus, especialmente, a graça de Vós haverdes dado a Vós mesmo neste Sacramento de amor, de nos haverdes dado por advogada a vossa Santíssima Mãe Maria, e de nos haverdes chamado a vos visitar nesta Igreja, nesta hora santa."},{"tipo":"sacerdote","texto":"Nós saudamos agora ó Jesus Sacramentado, o Vosso amantíssimo Coração, e entendemos saudá-lo por três motivos: primeiro em agradecimento por este grande dom; segundo, para compensar-vos todas as injúrias que tendes recebido de todos os inimigos deste Sacramento; terceiro, porque pretendemos com esta visita Vos adorar em todos os lugares da terra, onde Vós sois menos reverenciado e mais abandonado."},{"tipo":"assembleia","texto":"Divino Jesus, nós Vos amamos com todo o nosso coração. Nos arrependemos de Vos haver desgostado tantas vezes no passado e termos sido ingratos à vossa bondade infinita. Esperamos que, amparados com a Vossa divina graça, não mais tornemos a Vos ofender de agora em diante; e agora, miseráveis que somos, nos consagramos a Vós, vos damos as nossas almas, desejosos de, por amor a Vós, renunciarmos toda a nossa vontade, afeições e desejos, bem como tudo o que possuímos."},{"tipo":"sacerdote","texto":"De hoje em diante fazei de nós, ó Jesus, e de tudo o que possuímos o que desejares. Só vos pedimos e desejamos o Vosso santo amor, a perseverança final, e o cumprimento perfeito da Vossa vontade. Vos recomendamos as almas do Purgatório, especialmente as mais devotas do Santíssimo Sacramento, e de Maria Santíssima. Vos recomendamos ainda todos os pobres pecadores. Unimo-nos enfim, ó querido Salvador, todos os nossos afetos com os afetos do Vosso amoroso Coração, e assim unidos os oferecemos ao Vosso Pai Eterno, e o pedimos em vosso Nome, que por Vosso amor os aceite e nos conceda todas as graças e bênçãos do céu."},{"tipo":"nota","texto":"Cântico."},{"tipo":"nota","texto":"Leitura bíblica."},{"tipo":"nota","texto":"Cântico."},{"tipo":"sacerdote","texto":"Ó Jesus Sacramentado, vós sois a fonte de todos os bens. Vós nos dizeis: \"Se alguém tem sede, venha a mim e beba\" (Jo 7,37). Oh! Com que abundância os Santos sempre têm bebido as águas da graça nesta fonte do Santíssimo Sacramento, onde Jesus nos reparte todos os méritos de sua Paixão, conforme predisse o profeta: \"Ireis, cheios de alegria, tomar as águas das fontes do Salvador\" (Is 12,3)."},{"tipo":"assembleia","texto":"Ó Jesus amantíssimo, dulcíssimo e caríssimo, vós sois a vida, esperança, tesouro e único amor de nossas almas; oh! Quanto vos custou a permanência conosco neste Sacramento! Para ficardes sobre os nossos altares vos foi preciso morrer na cruz. E depois, neste Sacramento, quantas injúrias sofreis para estardes presente no meio de nós! Mas, venceu o Vosso amor, venceu o desejo que tendes de ser amado de nós."},{"tipo":"sacerdote","texto":"Vinde, pois, Senhor, vinde, encerrai-Vos no nosso coração e trancai-lhe a porta para sempre, a fim de que nenhuma criatura entre nele para roubar o amor que Vos devemos e queremos dar-Vos sem reserva. Reinai, ó amado Redentor, reinai sobre nós e possuí-nos; e, se alguma vez não Vos obedecermos perfeitamente, exortai-nos Senhor para que sejamos mais atentos em Vos amar, agradar e fazer a Vossa vontade."},{"tipo":"assembleia","texto":"Fazei Senhor que não desejemos nem busquemos outro prazer mais que o de Vos amar e sermos agradáveis a vós, Visitar-Vos muitas vezes nos altares, quedar-vos aos pés de vossos sacrários, entreter-nos convosco e receber-Vos na santa comunhão. Outros bens procurem quem os quiser, nós porém, só a vós amamos e só desejamos o tesouro do Vosso amor: isto só, e nada mais vos queremos pedir aos pés do altar."},{"tipo":"nota","texto":"Cântico."},{"tipo":"sacerdote","texto":"Fazei Senhor que nos esqueçamos de nós mesmos, para lembrar-nos somente da Vossa bondade. Ó bem-aventurados Serafins, vós que vos abrasais de amor diante da Santíssima Trindade, não vos admiramos pela vossa glória, mas pelo amor que consagrais a Deus; ensinai-nos o que devemos fazer para O amar e sermos-lhes agradáveis. Ó Bom Jesus, só a Vós queremos amar, só a Vós queremos agradar."},{"tipo":"sacerdote","texto":"Ó Cordeiro sem mancha, imolado por nós na cruz, lembrai-Vos que somos as almas que remistes com tantas dores e com a vossa própria morte. Fazei que sejais todo nosso e que nunca mais Vos percamos, já que Vos destes todo a nós e Vos dais ainda cada dia, doando-vos por nosso amor sobre os altares. Pedimos-vos a graça de sermos também nós todos vossos."},{"tipo":"assembleia","texto":"Neste momento, damo-nos todo a Vós, para que façais de nós o que Vos aprouver. Damos-vos a nossa vontade: prendei-a com as suaves cadeias do Vosso amor, a fim de que seja para sempre serva da Vossa santíssima vontade."},{"tipo":"sacerdote","texto":"Não queremos mais viver para satisfazer os nossos desejos, mas somente para contentar a Vossa vontade. Destruí em nós, ó amado Jesus, tudo o que Vos desagrada; dai-nos a graça de só pensar em Vos agradar, e de só querer o que Vós quereis. Amamos-vos, ó querido Salvador, de todo o nosso coração; amamos-vos porque quereis ser amado por nós; amamos-vos porque sois infinitamente digno do nosso amor. Pesa-nos, Senhor, não poder amar-Vos quanto o mereceis. Ah! Pudéssemos morrer por Vosso amor! Aceitai, Senhor, este nosso desejo e dai-nos o Vosso amor."},{"tipo":"sacerdote","texto":"Queremos agora, Senhor nosso Deus, receber a vossa bênção santíssima. Dignai-vos ó Jesus, abrasar o nosso coração de amor por vós e nos conceder as graças e bênçãos que emanam da vossa presença sacrossanta."},{"tipo":"nota","texto":"Bênção do Santíssimo completa."}]},{"slug":"outubro","mes":"Outubro","completo":true,"blocos":[{"tipo":"nota","texto":"Cântico para entrada do Santíssimo e incensação."},{"tipo":"nota","texto":"Cântico para início da Hora Santa: \"Ó Vinde a Nós, Espírito Santo\"."},{"tipo":"sacerdote","texto":"Ó amado Jesus, ensinou-nos São Francisco de Assis: \"pasme o homem todo, estremeça a terra inteira, rejubile o céu em altas vozes quando, sobre o altar, estiver nas mãos do sacerdote o Cristo, Filho de Deus vivo!\""},{"tipo":"assembleia","texto":"Nós cremos verdadeiramente e professamos que tu és o Filho Santo do Eterno Pai, nosso Salvador, presente sob as espécies eucarísticas e te adoramos nesta Hora Santa: \"ó grandeza maravilhosa, ó admirável condescendência! Ó humildade sublime, ó humilde sublimidade!\""},{"tipo":"sacerdote","texto":"Verdadeiramente humildade sublime e humilde sublimidade: \"o Senhor do universo, Deus e Filho de Deus, se humilha a ponto de se esconder, para nosso bem, na modesta aparência de pão... Nada de vós retenhais para vós mesmos, para que totalmente vos receba quem totalmente se vos dá.\""},{"tipo":"assembleia","texto":"Doce Amor, amor que nos consola e que nos alimenta para a vida eterna. Vós sois, ó Jesus, o nosso tudo. Neste momento de graça vos reverenciamos e nos curvamos ante a vossa presença com o mais profundo respeito, bendizemos a vossa Divina Majestade, glorificamos a vossa magnificência, e louvamos a vossa beleza infinita. Ó quão sublime este momento em que diante de vós vos submetemos o nosso coração com todos os seus afetos, a nossa alma com todas as suas potências e o nosso pensamento."},{"tipo":"assembleia","texto":"Só Vós, ó Jesus, sois a nossa consolação! Por isso humildemente vos pedimos: permita-nos neste momento de paz e amor descansarmos em vosso sacratíssimo Coração, pois, só vós sois a alegria e a felicidade de nossas almas! Só em vós elas, cansadas e oprimidas pelo peso do pecado e das suas nefastas consequências, encontram o alívio e o socorro de que tanto necessitam. Só a Vós, Senhor, todas as criaturas no céu e na terra devem render glória e adoração."},{"tipo":"sacerdote","texto":"Nós vos adoramos, ó Bom Jesus, em nome de todas as criaturas, em nome de tudo o que criastes, o céu com suas potências, a terra com tudo o que lhe é próprio e o mar com seus mistérios. Tudo tu criaste por amor e por misericórdia infinita. Nós te adoramos em nome das tuas criaturas, principalmente daquelas que não vos adoram."},{"tipo":"assembleia","texto":"E para que a nossa pobre adoração mais vos agrade, nós vos oferecemos, ó Divino Redentor, todos os atos de adoração dos santos apóstolos e confessores, dos gloriosos mártires e das santas virgens, dos Anjos que vos fazem guarda de honra aqui diante do sagrado tabernáculo, dos Arcanjos que estão diante do vosso trono no céu, e de todos os Querubins e Serafins, Potestades, Principados e Virtudes, Tronos e Dominações."},{"tipo":"sacerdote","texto":"Em particular, vos oferecemos, amado Jesus, a adoração do apóstolo São João, vosso amigo angélico, que na noite memorável da santa Ceia encostou a cabeça em vosso peito para ouvir o vosso coração; de São José vosso pai putativo que tanto vos ama e a quem escolhestes para ser o vosso provedor e guarda zeloso na vossa infância e sobretudo da Santíssima Virgem Maria, vossa mãe imaculada, que antes de conceber-vos em seu ventre já vos concebia em seu coração e que vos acompanhou por toda a vida desde o vosso nascimento na gruta de Belém até o momento em que fostes colocado no sepulcro pela nossa salvação."},{"tipo":"assembleia","texto":"Aceitai propício e benigno, ó divino Salvador nosso, este ato de adoração que vos fazemos, em união com os vossos anjos e santos e pelo Coração puríssimo de vossa Mãe Imaculada, e fazei que sempre nos aproximemos de vós com a mais viva fé, devoção e amor, a fim de termos a dita inefável de adorar-vos um dia com os anjos e santos, na eterna glória do céu."},{"tipo":"nota","texto":"Cântico."},{"tipo":"nota","texto":"Leitura bíblica."},{"tipo":"nota","texto":"Cântico."},{"tipo":"sacerdote","texto":"Recebei, ó Jesus sacramentado, este momento de adoração, momento em que minha alma vive a paz e o amor. Quão grande, Senhor, é a abundância da doçura que reservastes aos que vos temem, vos amam de todo o coração e vos servem! É verdadeiramente inefável a doçura da contemplação que concedeis aos que vos amam. Nisto particularmente me manifestastes a doçura de vosso amor: quando eu não era, vós me criastes e quando eu andava longe de vós, perdido no erro, vós me reconduzistes a vos servir e me destes o preceito de vos amar."},{"tipo":"assembleia","texto":"Ó fonte perene de amor, que direi de vós? Como poderia eu esquecer-me que vos dignastes lembrar-vos de mim, ainda depois de depravado e perdido? Além de toda esperança, usastes de misericórdia para com vosso servo, e acima de todo mérito me prodigalizastes vossa graça e amizade. Com que poderei agradecer-vos tal mercê? Será porventura mérito que eu vos sirva, quando toda criatura tem obrigação de vos servir? Não me deve parecer grande coisa que eu vos sirva; antes devo considerar grande e digno de admiração que vos digneis receber-me pobre e indigno como sou em vosso serviço e associar-me aos vossos servos prediletos."},{"tipo":"sacerdote","texto":"Vede, é vosso, Senhor, tudo que possuo e com que vos sirvo; entretanto, mais me servis vós a mim, do que eu a vós. Aí estão o céu e a terra, que criastes para uso do homem, e estão atentos a vosso aceno, a fazer cada dia o que lhes mandais. Mais ainda: os próprios anjos destinastes ao serviço do homem. Mas, acima de tudo isso, vós mesmo vos dignais servir ao homem, e prometestes ser a sua recompensa."},{"tipo":"assembleia","texto":"Que vos darei eu por esses benefícios sem conta? Oh! se pudera servir-vos todos os dias da minha vida! Se pudera, ainda que um só dia, prestar-vos condigno serviço! Na verdade, sois digno de todo serviço, de toda honra e glória eterna. Vós sois, verdadeiramente, meu Senhor, eu vosso pobre servidor, obrigado a servir-vos com todas as minhas forças, sem me cansar jamais de vos dar louvores. Assim o quero, assim o desejo: dignai-vos, Senhor, suprir o que me falta."},{"tipo":"sacerdote","texto":"Grande honra e glória é servir-vos e desprezar tudo por vosso amor. Porque copiosas graças alcançarão os que livremente se sujeitam ao vosso santíssimo serviço. Encontrarão suavíssima consolação do Espírito Santo os que por vós desprezam todos os deleites carnais. Conseguirão grande liberdade da alma os que por vosso nome entram na vereda estreita e se apartam de todos os cuidados mundanos."},{"tipo":"assembleia","texto":"Ó doce e amável servidão de Deus, que torna o homem verdadeiramente livre e santo! Ó sagrada servidão, que faz o homem agradável a Deus! Ó ditoso e nunca assaz desejado serviço, que nos mereceu o Bem soberano e adquire o gozo que há de durar para sempre!"},{"tipo":"nota","texto":"Bênção completa."}]},{"slug":"novembro","mes":"Novembro","completo":true,"blocos":[{"tipo":"nota","texto":"Cântico para entrada do Santíssimo e incensação."},{"tipo":"nota","texto":"Cântico para início da Hora Santa: \"Ó Vinde a Nós, Espírito Santo\"."},{"tipo":"assembleia","texto":"Senhor meu Jesus Cristo, que, por amor aos homens, ficais dia e noite neste Sacramento, todo cheio de misericórdia e amor, esperando, chamando e acolhendo todos os que vêm visitar-Vos, eu creio que estais presente no Sacramento do altar. Adoro-Vos do abismo do meu nada e agradeço-Vos todas as graças que me tendes feito, especialmente a de Vos terdes dado a mim neste Sacramento, a de me haverdes concedido por advogada Maria, vossa Mãe Santíssima, e finalmente, a de me haverdes chamado a visitar-Vos nesta Igreja."},{"tipo":"assembleia","texto":"Saúdo hoje o vosso Coração amantíssimo e quero saudá-lo por três fins: primeiro, em agradecimento pelo grande dom de Vós mesmo; segundo, em reparação das injúrias que tendes recebido, neste Sacramento, de todos os vossos inimigos; terceiro, com a intenção de Vos adorar, por esta visita, em todos os lugares da Terra onde Vós, neste divino Sacramento, estais menos reverenciado e mais abandonado."},{"tipo":"assembleia","texto":"Meu Jesus, amo-Vos de todo o meu coração. Arrependendo-me de, no passado, ter ofendido tantas vezes a vossa bondade infinita. Proponho, com a vossa graça, não mais Vos ofender no futuro. E nesta hora, embora miserável como sou, eu me consagro todo a Vós e Vos dou e entrego a minha vontade, os meus afetos, os meus desejos e tudo o que me pertence. Daqui em diante fazei de mim, e de tudo o que é meu, o que Vos aprouver. Somente Vos peço e quero o vosso santo amor, a perseverança final e o perfeito cumprimento da vossa vontade."},{"tipo":"assembleia","texto":"Recomendo-Vos as almas do Purgatório, especialmente as mais devotas do Santíssimo Sacramento e da Santíssima Virgem Maria. Recomendo-Vos também todos os pobres pecadores. Enfim, meu amado Salvador, uno todos os meus afetos aos afetos do vosso Coração amantíssimo e, assim unidos, eu os ofereço a vosso Eterno Pai, pedindo-Lhe, em Vosso nome e por vosso amor, que Se digne de os aceitar e atender. Assim seja."},{"tipo":"nota","texto":"Cântico."},{"tipo":"nota","texto":"Leitura bíblica."},{"tipo":"nota","texto":"Cântico."},{"tipo":"sacerdote","texto":"Ó Cristo Rei do universo, nosso Senhor e Redentor, com o coração alegre e cheio de esperança vos adoramos e bendizemos neste Santíssimo e Diviníssimo Sacramento do Altar pelo qual permaneces em nosso meio em Corpo e Sangue, Alma e Divindade e nos alimentas, fortalecendo-nos nesta caminhada rumo ao céu. Nós vos reverenciamos e afirmamos o vosso reinado sobre todo o universo, vos ofertamos o nosso coração e nele erguemos um trono de amor para que de hoje em diante o vosso amor tudo governe em nossa vida."},{"tipo":"assembleia","texto":"Mês de novembro, mês de amor e oração, mês dedicado a vós, ó Jesus, nosso soberano e salvador. É assim que queremos viver esses trinta dias: uma vida na vossa presença, uma vida em oração, uma vida em comunhão com a Igreja. Por isso, prostrados aos vossos pés vos pedimos: governai, ó Jesus, com vosso poder, a nossa paróquia, as nossas casas, as nossas famílias. Derramai sobre nós as vossas bênçãos e estendei as graças desta hora santa a todas as pessoas que ao redor deste altar vos glorificam, aquelas que não puderam vir e, também as que não vos conhecem."},{"tipo":"sacerdote","texto":"Em vossas mãos, Pai de misericórdia, entregamos as almas de todos os fiéis defuntos por quem ontem rezamos e de um modo todo especial aquelas que não têm ninguém para rezar por elas. Estendei, Senhor, a essas prisioneiras, os bens espirituais e os frutos de todas as santas missas que no dia de ontem foram celebradas e as indulgências que lucramos pela vossa misericordiosa benevolência. Abri, divino benfeitor, as portas do paraíso, para que, na vossa eterna paz, elas já descansem para sempre."},{"tipo":"assembleia","texto":"Entregamos-vos, Coração Santíssimo, neste momento de esplendor, o Apostolado da Oração, rede mundial de oração do Papa, que tanto bem tem feito às almas e espalhado no mundo a devoção a Vós, para que todos os fiéis recebam as bênçãos que desejais derramar no mundo por meio das doze promessas que revelastes à Santa Margarida Maria Alacoque, e esperamos que nossos louvores sejam aceitos por vossa divina majestade. Dai-nos, Rei dos reis, a graça de passarmos desta mesa de peregrinos à morada eterna, onde vos contemplaremos como sois. Concedei, humildemente rogamos-vos, que aqueles que agora vos adoram sob este véu sacramental, possam adorar-vos no céu pelos séculos sem fim."},{"tipo":"sacerdote","texto":"Ó clementíssimo Jesus, com que comparar o vosso amor por nós? Ou, que ação de graças poderia igualar os benefícios que nos fazes? Quão grandes e incompreensíveis são as graças que nos concedestes e todos os dias nos concedeis com liberalidade infinita, não obstante as nossas misérias e os nossos pecados. Queremos vos agradecer por tanto nos amardes ó Jesus!"},{"tipo":"assembleia","texto":"Nós vos agradecemos ó Deus e Senhor nosso por nos terdes dado a vida e todas as criaturas que destinastes ao nosso serviço, e por nos terdes feito guardiões da vossa criação e jardineiros da natureza que tão belamente fizestes. Ela é forte e cheia de encantos, generosa e graciosa, nela imprimistes as estações e os tempos para o nosso deleite, nos destes o que precisamos para saciar as nossas necessidades materiais e imprimistes em cada uma de suas particularidades os sinais de que nos amas, ó Senhor."},{"tipo":"sacerdote","texto":"Nós vos agradecemos ó piedosíssimo Jesus, vos terdes feito homem por nosso amor e morrido na cruz para nos salvar, resgatando-nos das profundezas do abismo infernal e lavando-nos do pecado original com vosso precioso sangue."},{"tipo":"assembleia","texto":"Nós vos agradecemos pela Santa Igreja Católica que fundastes na terra, os santos sacramentos que instituístes, por nos terdes feito nascer na fé católica e apostólica, nela nos ter conservado até hoje, e por não terdes nos deixado morrer em pecado, dando-nos o tempo e a graça suficiente para fazermos penitência."},{"tipo":"sacerdote","texto":"Nós vos agradecemos todas as graças que continuamente nos concedeis para a nossa santificação, bem como todos os benefícios que a cada passo nos dispensais."},{"tipo":"assembleia","texto":"De modo especial, Senhor, queremos vos agradecer pelo Santíssimo Sacramento da Eucaristia, pelo qual vos fazes presente entre nós e nos alimentas a alma, dando-nos vida, força, consolação e alento."},{"tipo":"sacerdote","texto":"Nós vos agradecemos hoje, em particular as graças que nos concedes nesta hora santa, em que nos permites estarmos juntos, diante de vossa presença. Desta Hóstia Santa, Pão Vivo descido do Céu, onde pulsa de amor o vosso Coração, fonte inesgotável de todas as graças e bênçãos, derramai sobre a vossa Igreja e sobre o Santo Padre o Papa, sobre a nossa diocese e sobre o nosso bispo, sobre a nossa paróquia, sobre o nosso pároco e todos os nossos padres, sobre os coordenadores e membros das pastorais, movimentos e associações as virtudes da santidade, unidade, da perseverança em vosso serviço e do amor que devemos ter para com a Sagrada Eucaristia."},{"tipo":"assembleia","texto":"Ó Jesus amável, desejamos que toda a nossa vida seja um ato contínuo de agradecimento, por tudo quanto fizestes por nós com tanta bondade e misericórdia. Fazei que eu vos possa louvar e bendizer num hino perpétuo de ação de graças, com todos os anjos e santos do Céu, pelos séculos dos séculos. Amém."},{"tipo":"nota","texto":"Bênção do Santíssimo completa."}]},{"slug":"dezembro","mes":"Dezembro","completo":true,"blocos":[{"tipo":"nota","texto":"Cântico para entrada do Santíssimo e incensação."},{"tipo":"nota","texto":"Cântico para início da Hora Santa: \"Ó Vinde a Nós, Espírito Santo\"."},{"tipo":"assembleia","texto":"Ó dulcíssimo Jesus, pedimos-vos nesta hora, por intercessão da Virgem Maria, vossa Santíssima Mãe e Senhora do Santíssimo Sacramento, que mereceu unicamente por graça divina trazer em seu seio puríssimo a vós, Verbo de Deus que se entregou por nós na Cruz e nos alimenta com seu Corpo e Sangue na Mesa da Comunhão. Concedei-nos um amor semelhante ao que ela vos tem, para que a nossa adoração seja perfeita e as nossas palavras e ações segundo a vossa vontade. Dai-nos, nesta hora, o amor que vos teve São José, que diligentemente bateu em todas as portas dos albergues de Belém, desejando que vós, ó Bom Senhor, nascesses com o conforto e a dignidade humana. Foi ele, que não achando lugar, vos preparou, com Maria, a manjedoura pobre e simples, mas adornada de amor, para que repousasses. Dai-nos ainda a esperança dos pastores que acorreram à piedosa Lapa de Belém, tocados pela mensagem dos anjos, e vos adoraram. Que seja, como foi aquela em que viveram todos esses bem-aventurados, esta nossa Hora Santa deste mês de dezembro."},{"tipo":"nota","texto":"(Rezar a dezena do terço pelas vocações sacerdotais e religiosas.)"},{"tipo":"nota","texto":"Cântico."},{"tipo":"nota","texto":"Diálogo com o Senhor."},{"tipo":"sacerdote","texto":"Ó Jesus Sacramentado, vós sois a fonte de todos os bens. Vós nos dizeis: \"Se alguém tem sede, venha a mim e beba\" (Jo 7,37). Oh! Com que abundância os Santos sempre têm bebido as águas da graça nesta fonte do Santíssimo Sacramento, onde Jesus nos reparte todos os méritos de sua Paixão, conforme predisse o profeta: \"Ireis, cheios de alegria, tomar as águas das fontes do Salvador\" (Is 12,3)."},{"tipo":"assembleia","texto":"Ó Jesus amantíssimo, dulcíssimo e caríssimo, vós sois a vida, esperança, tesouro e único amor de nossas almas; oh! Quanto vos custou a permanência conosco neste Sacramento! Para ficardes sobre os nossos altares vos foi preciso morrer na cruz. E depois, neste Sacramento, quantas injúrias sofreis para estardes presente no meio de nós! Mas venceu o Vosso amor, venceu o desejo que tendes de ser amado de nós."},{"tipo":"sacerdote","texto":"Vinde, pois, Senhor, vinde, encerrai-Vos no nosso coração e trancai-lhe a porta para sempre, a fim de que nenhuma criatura entre nele para roubar o amor que Vos devemos e queremos dar-Vos sem reserva. Reinai, ó amado Redentor, sobre nós e possuí-nos; e, se alguma vez não Vos obedecermos perfeitamente, exortai-nos Senhor para que sejamos mais atentos em Vos amar, agradar e fazer a Vossa vontade."},{"tipo":"assembleia","texto":"Fazei Senhor que não desejemos nem busquemos outro prazer mais que o de Vos amar e sermos agradáveis a vós, visitar-Vos muitas vezes nos altares, quedar-nos aos pés de vossos sacrários, entreter-nos convosco e receber-Vos na santa comunhão. Outros bens procurem quem os quiser, nós porém, só a vós amamos e só desejamos o tesouro do Vosso amor: isto só, e nada mais vos queremos pedir aos pés do altar."},{"tipo":"sacerdote","texto":"Fazei Senhor que nos esqueçamos de nós mesmos, para lembrar-nos somente da Vossa bondade. Ó bem-aventurados Serafins, vós que vos abrasais de amor diante da Santíssima Trindade, não vos admiramos pela vossa glória, mas pelo amor que consagrais a Deus; ensinai-nos o que devemos fazer para O amar e sermos-lhe agradáveis. Ó Bom Jesus, só a Vós queremos amar, só a Vós queremos agradar."},{"tipo":"sacerdote","texto":"Ó Cordeiro sem mancha, imolado por nós na cruz, lembrai-Vos que somos as almas que remites com tantas dores e com a vossa própria morte. Fazei que sejamos todo nosso e que nunca mais Vos percamos, já que Vos destes todo a nós e Vos dais ainda cada dia, doando-vos por nosso amor sobre os altares. Pedimos-vos a graça de sermos também nós todos vossos."},{"tipo":"assembleia","texto":"Neste momento, damo-nos todo a Vós, para que façais de nós o que Vos aprouver. Damos-vos a nossa vontade: prendei-a com as suaves cadeias do Vosso amor, a fim de que seja para sempre serva da Vossa santíssima vontade."},{"tipo":"sacerdote","texto":"Não queremos mais viver para satisfazer os nossos desejos, mas somente para contentar a Vossa vontade. Destruí em nós, ó amado Jesus, tudo o que Vos desagrada; dai-nos a graça de só pensar em Vos agradar, e de só querer o que Vós quereis. Amamos-vos, ó querido Salvador, de todo o nosso coração; amamos-vos porque quereis ser amado por nós; amamos-vos porque sois infinitamente digno do nosso amor. Pesa-nos, Senhor, não poder amar-Vos quanto o mereceis. Ah! Pudéssemos morrer por Vosso amor! Aceitai, Senhor, este nosso desejo e dai-nos o Vosso amor."},{"tipo":"nota","texto":"Cântico."},{"tipo":"nota","texto":"Leitura bíblica."},{"tipo":"nota","texto":"Cântico."},{"tipo":"sacerdote","texto":"Recebei, ó Jesus sacramentado, este momento de adoração, momento em que minha alma vive a paz e o amor. Quão grande, Senhor, é a abundância da doçura que reservastes aos que vos temem, vos amam de todo o coração e vos servem! É verdadeiramente inefável a doçura da contemplação que concedeis aos que vos amam. Nisto particularmente me manifestastes a doçura de vosso amor: quando eu não era, vós me criastes e quando eu andava longe de vós, perdido no erro, vós me reconduzistes a vos servir e me destes o preceito de vos amar."},{"tipo":"assembleia","texto":"Ó fonte perene de amor, que direi de vós? Como poderia eu esquecer-me que vos dignastes lembrar-vos de mim, ainda depois de depravado e perdido? Além de toda esperança, usastes de misericórdia para com vosso servo, e acima de todo mérito me prodigalizastes vossa graça e amizade. Com que poderei agradecer-vos tal mercê? Será porventura mérito que eu vos sirva, quando toda criatura tem obrigação de vos servir? Não me deve parecer grande coisa que eu vos sirva; antes devo considerar grande e digno de admiração que vos digneis receber-me pobre e indigno como sou em vosso serviço e associar-me aos vossos servos prediletos."},{"tipo":"sacerdote","texto":"Vede, é vosso, Senhor, tudo que possuo e com que vos sirvo; entretanto, mais me servis vós a mim, do que eu a vós. Aí estão o céu e a terra, que criastes para uso do homem, e estão atentos a vosso aceno, a fazer cada dia o que lhes mandais. Mais ainda: os próprios anjos destinastes ao serviço do homem. Mas, acima de tudo isso, vós mesmo vos dignais servir ao homem, e prometestes ser a sua recompensa."},{"tipo":"assembleia","texto":"Que vos darei eu por esses benefícios sem conta? Oh! Se pudera servir-vos todos os dias da minha vida! Se pudera, ainda que um só dia, prestar-vos condigno serviço! Na verdade, sois digno de todo serviço, de toda honra e glória eterna. Vós sois, verdadeiramente, meu Senhor, eu vosso pobre servidor, obrigado a servir-vos com todas as minhas forças, sem me cansar jamais de vos dar louvores. Assim o quero, assim o desejo: dignai-vos, Senhor, suprir o que me falta."},{"tipo":"sacerdote","texto":"Grande honra e glória é servir-vos e desprezar tudo por vosso amor. Porque copiosas graças alcançarão os que livremente se sujeitam ao vosso santíssimo serviço. Encontrarão suavíssima consolação do Espírito Santo os que por vós desprezam todos os deleites carnais. Conseguirão grande liberdade da alma os que por vosso nome entram na vereda estreita e se apartam de todos os cuidados mundanos."},{"tipo":"assembleia","texto":"Ó doce e amável servidão de Deus, que torna o homem verdadeiramente livre e santo! Ó sagrada servidão, que faz o homem agradável a Deus! Ó ditoso e nunca assaz desejado serviço, que nos mereceu o Bem soberano e adquire o gozo que há de durar para sempre!"},{"tipo":"nota","texto":"Bênção do Santíssimo Completa."}]}];

const hsel = (id) => document.getElementById(id);

function renderMonthList() {
  const list = hsel('hsMonthList');
  list.innerHTML = '';
  HORA_SANTA_MESES.forEach((m, idx) => {
    const btn = document.createElement('button');
    btn.className = 'book-btn';
    const legenda = m.completo ? `${m.blocos.length} partes` : 'texto incompleto na fonte';
    btn.innerHTML = `<span>${m.mes}</span><small>${legenda}</small>`;
    btn.addEventListener('click', () => openMonth(idx));
    list.appendChild(btn);
  });
}

let currentMesIdx = null;

function openMonth(idx) {
  currentMesIdx = idx;
  if (window.MinhaLiturgiaNarration) window.MinhaLiturgiaNarration.stop();
  const mes = HORA_SANTA_MESES[idx];
  hsel('hsReaderTitle').textContent = `Hora Santa — ${mes.mes}`;

  const note = hsel('hsIncompleteNote');
  if (!mes.completo) {
    note.textContent = 'O documento de origem só traz os cânticos de abertura deste mês — o restante do roteiro não estava disponível para incluir aqui.';
    note.classList.remove('hidden');
  } else {
    note.classList.add('hidden');
  }

  const body = hsel('hsBody');
  body.innerHTML = '';
  mes.blocos.forEach((bloco) => {
    const p = document.createElement('p');
    if (bloco.tipo === 'sacerdote') {
      p.className = 'eu-line eu-sacerdote';
      p.innerHTML = `<span class="eu-label">Padre</span>${bloco.texto}`;
    } else if (bloco.tipo === 'assembleia') {
      p.className = 'eu-line eu-assembleia';
      p.innerHTML = `<span class="eu-label">Povo</span>${bloco.texto}`;
    } else {
      p.className = 'eu-line eu-nota';
      p.textContent = bloco.texto;
    }
    body.appendChild(p);
  });

  hsel('hs-step-list').classList.add('hidden');
  hsel('hs-step-reader').classList.remove('hidden');
  body.scrollIntoView({ block: 'start' });
}

function backToMonthList() {
  if (window.MinhaLiturgiaNarration) window.MinhaLiturgiaNarration.stop();
  hsel('hs-step-reader').classList.add('hidden');
  hsel('hs-step-list').classList.remove('hidden');
}

function initHoraSanta() {
  renderMonthList();
  document.querySelectorAll('[data-back-to="hs-list"]').forEach((b) => b.addEventListener('click', backToMonthList));
  hsel('narrateHoraSantaBtn').addEventListener('click', () => {
    if (currentMesIdx === null || !window.MinhaLiturgiaNarration) return;
    const mes = HORA_SANTA_MESES[currentMesIdx];
    const labels = { sacerdote: 'Padre', assembleia: 'Povo' };
    window.MinhaLiturgiaNarration.toggle(hsel('narrateHoraSantaBtn'), () =>
      `Hora Santa de ${mes.mes}. ${window.MinhaLiturgiaNarration.textFromBlocos(mes.blocos, labels)}`
    );
  });
}

window.MinhaLiturgiaHoraSanta = { initHoraSanta };
